#include <math.h>

MagickBooleanType AutoGammaImage(Image *image, ExceptionInfo *exception) {
  if (image == NULL || exception == NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), 
      ResourceLimitError, "InvalidImagePointerException", "");
    return MagickFalse;
  }

  double mean = GetImageMean(image);
  if (mean <= 0.0 || mean >= 1.0) {
    (void) ThrowMagickException(exception, GetMagickModule(), 
      ResourceLimitError, "InvalidMeanValueException", "Mean value out of range");
    return MagickFalse;
  }

  double log_mean = log(mean);
  if (log_mean == 0.0) {
    return MagickTrue; // No adjustment needed
  }

  double gamma = 1.0 / log_mean;

  if (image->channel_mask == DefaultChannel) {
    MagickBooleanType status = AdjustImageGamma(image, gamma, exception);
    if (status == MagickFalse) {
      return MagickFalse;
    }
  } else {
    for (size_t channel = 0; channel < image->number_channels; ++channel) {
      double channel_mean = GetImageChannelMean(image, channel);
      if (channel_mean <= 0.0 || channel_mean >= 1.0) {
        (void) ThrowMagickException(exception, GetMagickModule(), 
          ResourceLimitError, "InvalidChannelMeanValueException", "Channel mean value out of range");
        return MagickFalse;
      }

      double channel_log_mean = log(channel_mean);
      if (channel_log_mean == 0.0) {
        continue; // No adjustment needed for this channel
      }

      double channel_gamma = 1.0 / channel_log_mean;
      MagickBooleanType status = AdjustImageChannelGamma(image, channel, channel_gamma, exception);
      if (status == MagickFalse) {
        return MagickFalse;
      }
    }
  }

  return MagickTrue;
}
